module TopModule (
    input  x,
    input  y,
    output z
);
    assign z = (x ^ y) & x;
endmodule

module tb_TopModule;
    logic x, y;
    logic z;

    TopModule u_uut (
        .x(x),
        .y(y),
        .z(z)
    );

    initial begin
        integer i;
        logic expected_z;

        for (i = 0; i < 4; i = i + 1) {
            {x, y} = i[1:0];
            #10;
            // Independent behavioural model
            expected_z = (x ^ y) & x;
            if (z !== expected_z) begin
                $display("SELFTEST FAIL: x=%b, y=%b => z=%b, expected %b", x, y, z, expected_z);
                $finish;
            end
        }
        $display("SELFTEST PASS");
        $finish;
    end
endmodule

